function longestPalindrome(s) {
    let res = "";
    for (let i = 0; i < s.length; i++) {
        // Odd
        let l = i, r = i;
        while (l >= 0 && r < s.length && s[l] === s[r]) {
            if (r - l + 1 > res.length) res = s.slice(l, r + 1);
            l--; r++;
        }
        // Even
        l = i; r = i + 1;
        while (l >= 0 && r < s.length && s[l] === s[r]) {
            if (r - l + 1 > res.length) res = s.slice(l, r + 1);
            l--; r++;
        }
    }
    return res;
}
